79	        if (replayed != null) {
80	            return replayed;
81	        }
82	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "CREATE");
83	        if (concurrent != null) {
84	            return concurrent;
85	        }
86	
87	        if (observationRepository.findCurrentForUpdate(request.observationId()).isPresent()) {
88	            throw ApiException.conflict("observation already exists: " + request.observationId(), null);
89	        }
90	        ObservationSnapshot snapshot = ObservationSnapshot.live(request.observationId(), 1, 1,
91	                request.location(), request.reading(), request.note());
92	        try {
93	            observationRepository.insertCurrent(snapshot);
94	        } catch (DuplicateKeyException e) {
95	            // 并发创建同一 observationId：由主键串行化，后到者按冲突处理
96	            throw ApiException.conflict("observation already exists: " + request.observationId(), null);
97	        }
98	        observationRepository.insertVersion(snapshot);
99	        return complete(request.requestId(), HttpStatus.CREATED, ObservationResponse.of(snapshot));
100	    }
