102	    /**
103	     * 离线提交：基于 baseVersion 的三方合并。合并结果与当前完全相同则不加版本，否则版本加一。
104	     */
105	    @Transactional
106	    public WriteOutcome merge(String observationId, MergeObservationRequest request) {
107	        String fingerprint = fingerprint("MERGE", observationId, String.valueOf(request.baseVersion()),
108	                request.location(), request.reading(), request.note());
109	        WriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
110	        if (replayed != null) {
111	            return replayed;
112	        }
113	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "MERGE");
114	        if (concurrent != null) {
115	            return concurrent;
116	        }
117	
118	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
119	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
120	        if (current.deleted()) {
121	            throw ApiException.gone("observation already deleted: " + observationId);
122	        }
123	        ObservationSnapshot base = observationRepository.findVersion(observationId, request.baseVersion())
124	                .orElseThrow(() -> ApiException.notFound(
125	                        "base version not found: " + observationId + "@" + request.baseVersion()));
126	        if (base.generation() != current.generation()) {
127	            // 恢复后代次已前进：删除前（旧代次）的离线修改不得直接灌入恢复后的记录，客户端须重读新基线。
