159	     */
160	    @Transactional
161	    public WriteOutcome delete(String observationId, DeleteObservationRequest request) {
162	        String fingerprint = fingerprint("DELETE", observationId, String.valueOf(request.expectedVersion()));
163	        WriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
164	        if (replayed != null) {
165	            return replayed;
166	        }
167	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "DELETE");
168	        if (concurrent != null) {
169	            return concurrent;
170	        }
171	
172	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
173	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
174	        if (current.deleted()) {
175	            throw ApiException.gone("observation already deleted: " + observationId);
176	        }
177	        if (request.expectedVersion() != current.version()) {
178	            throw ApiException.conflict("expectedVersion mismatch", current.version());
179	        }
180	        ObservationSnapshot tombstone = ObservationSnapshot.tombstone(
181	                observationId, current.version() + 1, current.generation());
182	        observationRepository.markDeleted(observationId, tombstone.version());
183	        observationRepository.insertVersion(tombstone);
184	        return complete(request.requestId(), HttpStatus.OK, ObservationResponse.of(tombstone));
185	    }
186	
187	    /**
188	     * 墓碑显式恢复：仅当当前为墓碑且 expectedVersion 匹配当前墓碑版本时允许恢复。
189	     * 来源必须是本记录已存在的非墓碑历史版本（允许跨代次）；复制其地点、读数与备注，
190	     * 生成“当前墓碑版本 + 1”的新快照，不回退版本、不改写原快照/冲突解决记录/墓碑，合并代次加一。
191	     */
192	    @Transactional
193	    public WriteOutcome restore(String observationId, RestoreObservationRequest request) {
194	        String reason = request.reason() == null ? null : request.reason().trim();
195	        String fingerprint = fingerprint("RESTORE", observationId,
196	                String.valueOf(request.expectedVersion()), String.valueOf(request.sourceVersion()), reason);
197	        WriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
198	        if (replayed != null) {
199	            return replayed;
200	        }
201	        WriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "RESTORE");
202	        if (concurrent != null) {
203	            return concurrent;
204	        }
205	
206	        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
207	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
208	        // 当前非墓碑：无可恢复的墓碑，返回 409 并携带当前版本。
209	        if (!current.deleted()) {
210	            throw ApiException.conflict("observation is not a tombstone: " + observationId, current.version());
211	        }
212	        if (request.expectedVersion() != current.version()) {
213	            throw ApiException.conflict("expectedVersion mismatch", current.version());
214	        }
215	        ObservationSnapshot source = observationRepository.findVersion(observationId, request.sourceVersion())
216	                .orElseThrow(() -> ApiException.notFound(
217	                        "source version not found: " + observationId + "@" + request.sourceVersion()));
218	        // 来源为墓碑：无法从墓碑复制业务内容，返回 422。
219	        if (source.deleted()) {
220	            throw ApiException.unprocessableEntity(
221	                    "source version must not be a tombstone: " + observationId + "@" + request.sourceVersion());
222	        }
223	
224	        int newVersion = current.version() + 1;
225	        int newGeneration = current.generation() + 1;
226	        ObservationSnapshot restored = ObservationSnapshot.live(observationId, newVersion, newGeneration,
227	                source.location(), source.reading(), source.note());
228	        observationRepository.restoreCurrent(restored);
229	        observationRepository.insertVersion(restored);
230	        restoreHistoryRepository.insert(new RestoreHistoryRecord(
231	                observationId, request.requestId(), current.version(), newVersion,
232	                source.version(), current.generation(), newGeneration, reason, Instant.now(clock)));
233	        return complete(request.requestId(), HttpStatus.OK, ObservationResponse.of(restored));
234	    }
