236	    /**
237	     * 查询当前内容；墓碑只返回删除状态和版本。
238	     */
239	    @Transactional(readOnly = true)
240	    public ObservationResponse getCurrent(String observationId) {
241	        ObservationSnapshot current = observationRepository.findCurrent(observationId)
242	                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
243	        return ObservationResponse.of(current);
244	    }
